  {"id":"P13","spot":13,"nums":{"a":13,"b":5,"m":2},"q":"Nina picks 13 apples in the morning and 5 apples after lunch. Kai picks 2 times as many apples. How many apples does Kai pick?","choices":["36","18","23","31"],"answer":"36","slips":{"18":{"tag":"Did only the first step","say":"13 + 5 = 18. That is step 1. Step 2: 2 × 18 = 36."},"23":{"tag":"Multiplied only one part","say":"Add first: 13 + 5 = 18. Then 2 × 18 = 36."},"31":{"tag":"Multiplied only one part","say":"Add first: 13 + 5 = 18. Then 2 × 18 = 36."}},"hint":"Step 1: add 13 + 5. Step 2: multiply by 2.","explanation":"Step 1: 13 + 5 = 18. Step 2: 2 × 18 = 36.","explain":{"work":["13 + 5 = 18","2 × 18 = 36"]}},
  {"id":"P14","spot":14,"nums":{"c":60,"g":5,"k":4},"q":"Mia has 60 markers. Each cup holds 5 markers. Mia filled 4 cups. Part A: Which equation shows how many markers are left, n?","choices":["60 − 5 − 4 = n","60 + 5 × 4 = n","60 − 5 × 4 = n","60 − 5 × 2 = n"],"answer":"60 − 5 × 4 = n","slips":{"60 − 5 × 2 = n":{"tag":"Used the wrong number of cups","say":"Mia filled 4 cups. 5 × 4 markers are gone. 60 − 5 × 4 = n."},"60 − 5 − 4 = n":{"tag":"Did not multiply","say":"4 cups of 5 is 5 × 4. 60 − 5 × 4 = n."},"60 + 5 × 4 = n":{"tag":"Added instead of subtracting","say":"Left means take away. 60 − 5 × 4 = n."}},"hint":"4 cups of 5 is 5 × 4. Take that away from 60.","explanation":"Mia starts with 60. 4 cups of 5 is 5 × 4. So 60 − 5 × 4 = n.","explain":{"work":["60 − 5 × 4 = n"]}},
  {"id":"P15","spot":15,"nums":{"c":60,"g":5,"k":4},"q":"Mia has 60 markers. Each cup holds 5 markers. Mia filled 4 cups. Part B: How many markers are left?","choices":["55","40","20","51"],"answer":"40","slips":{"20":{"tag":"Found the markers in the cups, not the ones left","say":"5 × 4 = 20 are in the cups. Left: 60 − 20 = 40."},"51":{"tag":"Did not multiply","say":"Multiply first: 5 × 4 = 20. Then 60 − 20 = 40."},"55":{"tag":"Took away only 1 group","say":"4 cups of 5: 5 × 4 = 20. 60 − 20 = 40."}},"hint":"Multiply first: 5 × 4. Then subtract from 60.","explanation":"Multiply first: 5 × 4 = 20. Then subtract: 60 − 20 = 40.","explain":{"work":["5 × 4 = 20","60 − 20 = 40"]}}
